#!/bin/bash
echo '<!DOCTYPE html><html><head><title>PROJECT VIGIL</title><style>body{background:#080a06;color:#a4b28d;font-family:monospace;padding:20px;}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:20px;}.card{background:#10140e;border:1px solid #38402f;padding:20px;border-radius:4px;}h1{color:#d1d5cb;border-bottom:2px solid #38402f;padding-bottom:10px;}h2{color:#ffb000;margin-top:0;}.btn{background:#151c12;border:1px solid #455239;color:#a4b28d;padding:8px;width:100%;cursor:pointer;font-family:monospace;font-weight:bold;margin-top:10px;}.btn:hover{color:#00ff66;border-color:#00ff66;}</style></head><body><h1>🛰️ PROJECT VIGIL // COMMAND MATRIX</h1><div id="status" style="color:#00ff66;font-weight:bold;margin-bottom:20px;">LINK ACTIVE</div><div class="grid" id="container"></div>' > index.html
echo '<script>async function update(){try{const r=await fetch("/api/grid?t="+Date.now());const d=await r.json();let h="";for(const id in d){const dev=d[id];h+=`<div class="card"><h2>🎯 NODE: ${id}</h2><div>PROFILE: ${dev.type}</div><div>IP ROUTE: ${dev.ip}</div><div>STATUS:  ${dev.state}</div><button class="btn" onclick="toggle(\x27${id}\x27)">TOGGLE RELAY</button></div>`;}document.getElementById("container").innerHTML=h||"<div>SCANNING AIRWAVES...</div>";}catch(e){document.getElementById("status").innerText="METRIC DROP";}}async function toggle(id){await fetch("/api/toggle",{method:"POST",body:JSON.stringify({device_id:id})});update();}setInterval(update,2000);window.onload=update;</script></body></html>' >> index.html
